import{d as l,C as a,o as g,c as h,a3 as e,E as s,j as n,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第八章","description":"《正易心法》第八章——经卦重卦，或离或合：纵横施设有二气老少、三代祖孙、对待、真假、胎甲、错综六种维度，理无不在，故《易》道大。","frontmatter":{"title":"正易心法·第八章","description":"《正易心法》第八章——经卦重卦，或离或合：纵横施设有二气老少、三代祖孙、对待、真假、胎甲、错综六种维度，理无不在，故《易》道大。","category":"guide","aliases":["正易心法第八章","经卦重卦或离或合","纵横施设"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-08.md","filePath":"yijing/zheng-yi-xin-fa/chapter-08.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-08.md"},x=l({...c,setup(u){const o=[{id:"z8-01",label:"一、或离或合",showLabel:!0,sentences:[["经卦重卦，或离或合。",{text:"纵横",glossary:"zongheng"},"施设，理无不在。"]],note:["经卦（三爻的八卦）与重卦（六爻的六十四卦），可以分离也可以组合；纵横排列施设，道理无处不在。（「离」是把重卦拆回上下卦，「合」是把经卦叠成重卦。这是本章的总纲：同一套卦画，可以从许多维度展开。）"]},{id:"z8-02",label:"二、若为诸图",showLabel:!0,sentences:[["纵横，谓若为",{text:"诸图",glossary:"zhutu"},"，"]],note:["所谓「纵横」，是说可以排成各种图式。（「诸图」指陈抟一脉流传的各类易图——河图、洛书、先天图、后天图、太极图等。本章等于在说：这些图不是孤立的，都是同一套卦画的不同展开维度。）"]},{id:"z8-03",label:"三、六种施设",showLabel:!0,sentences:[["或有",{text:"二气老少之渐",glossary:"laoshao"},"，或有",{text:"三代祖孙之别",glossary:"zusun"},"，或有",{text:"对待之理",glossary:"duidai"},"，或有",{text:"真假之义",glossary:"zhenjia"},"，或有",{text:"胎甲之象",glossary:"taijia"},"，或有",{text:"错综之占",glossary:"cuozong"},"。"]],note:["（这六种，就是全部纵横施设的维度：）或有阴阳二气老少渐变的层次（老阳九、少阳七、少阴八、老阴六：九六为动爻，七八为静爻）；或有三代祖孙的卦级区别（经卦为祖、重卦为父、互卦为孙）；或有对立相待的道理（错卦：阴阳全反，如乾与坤、坎与离）；或有真卦假卦的义理（本卦为真，变卦、伏卦为假）；或有胎育萌甲的象（坤为胎、复为甲，阴阳转折最微妙的瞬间）；或有错综变化的占法（错卦阴阳互换、综卦上下翻转）。"]},{id:"z8-04",label:"四、皆具妙理",showLabel:!0,sentences:[["唯其施设，皆具妙理，无所往而不可。"]],note:["这六种施设，每一种都包含妙理，用到哪里都可以。（这是对第四章批评的正面回应：汉儒只用八个字概括八卦，是因为只看到卦的一个维度；这里的六种维度，每一种都有完整的道理。）"]},{id:"z8-05",label:"五、包括万象",showLabel:!0,sentences:[["此所谓包括万象，而《易》道所以大也。"]],note:["这就是所谓「包括万象」，也是《易》道之所以广大的原因。（《系辞传》说《易》道大，是从外部宣告「《易》与天地准」；麻衣说《易》道大，是从内部展示「卦画本身有无穷的展开方式」——前者是结论，后者是推导。）"]}],i=[{id:"zongheng",term:"纵横",pinyin:"zòng héng",meaning:"纵向横向，多维展开。指卦画可从多个维度排列分析。"},{id:"zhutu",term:"诸图",pinyin:"zhū tú",meaning:"各种图式。指陈抟一脉流传的易图：河图、洛书、先天后天八卦图、太极图等。"},{id:"laoshao",term:"二气老少之渐",pinyin:"lǎo shào zhī jiàn",meaning:"阴阳二气老嫩渐变：老阳九、少阳七、少阴八、老阴六。九六为动爻（变），七八为静爻（不变）。"},{id:"zusun",term:"三代祖孙之别",pinyin:"sān dài zǔ sūn",meaning:"经卦→重卦→互卦的层级关系：经卦为祖，重卦为父，互卦为孙。"},{id:"duidai",term:"对待之理",pinyin:"duì dài zhī lǐ",meaning:"卦的对卦（错卦）关系，阴阳完全相反：乾与坤、坎与离、既济与未济。"},{id:"zhenjia",term:"真假之义",pinyin:"zhēn jiǎ zhī yì",meaning:"本卦与变卦、伏卦的关系。真为本卦（当下显现），假为变卦（爻变之后）或伏卦（隐藏的对宫）。"},{id:"taijia",term:"胎甲之象",pinyin:"tāi jiǎ zhī xiàng",meaning:"卦气萌生、潜藏未发的状态：坤为胎（纯阴，阳气全藏），复为甲（一阳来复，初爻生阳）。"},{id:"cuozong",term:"错综之占",pinyin:"cuò zōng zhī zhàn",meaning:"错卦（阴阳互换）与综卦（上下翻转）的占法。占卦时本卦、错卦、综卦可得三个维度的信息。"}];return(b,t)=>{const r=a("DaoTextReading"),d=a("DaoKeywordCards");return g(),h("div",null,[t[0]||(t[0]=e("",16)),s(r,{colophon:"或离或合 · 纵横施设 · 六种维度 · 包括万象",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第八章原文",sections:o,glossary:i}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(d,{items:[{term:"经卦 · 重卦",pinyin:["jīng","guà"],meaning:"经卦是三爻的八卦（基本单元）；重卦是两经卦相叠的六十四卦。「或离」即拆回上下卦，「或合」即叠成重卦。"},{term:"二气老少之渐",pinyin:["lǎo","shào"],meaning:"老阳九、少阳七、少阴八、老阴六。九六为动爻（变），七八为静爻（不变）——这是蓍草筮法与十二消息卦共同的基础。"},{term:"三代祖孙之别",pinyin:["zǔ","sūn"],meaning:"经卦（祖）→ 重卦（父）→ 互卦（孙）。如泰卦：祖为坤乾，父为泰本卦，孙为互卦归妹。"},{term:"对待之理",pinyin:["duì","dài"],meaning:"错卦关系——阴阳完全相反：乾↔坤、坎↔离、既济↔未济。相反相成，是一阴一阳之谓道的卦画体现。"},{term:"真假之义",pinyin:["zhēn","jiǎ"],meaning:"本卦为真（当下显现），变卦与伏卦为假（潜藏或变动之后）。呼应第六章「辞外见意」。"},{term:"胎甲之象",pinyin:["tāi","jiǎ"],meaning:"坤为胎（纯阴，阳气全藏），复为甲（一阳来复，破甲而出）——阴阳由无到有、由隐到显的转折瞬间。"},{term:"错综之占",pinyin:["cuò","zōng"],meaning:"错卦（阴阳互换）、综卦（上下翻转）。占时本卦＋综卦＋错卦，可得当下、对方、反向三个维度。"}]}),t[3]||(t[3]=e("",25))])}}});export{y as __pageData,x as default};
